import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
import {MAPS} from '../../dist/maps.mjs';
import {createRasterizer} from './browser-raster.mjs';
const dir=fileURLToPath(new URL('./',import.meta.url)),root=fileURLToPath(new URL('../../',import.meta.url));
const require=createRequire(import.meta.url),deps=path.join(os.homedir(),'.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules');
const sharp=require(require.resolve('sharp',{paths:[deps]}));
const descriptions={
  "forest": "保留64格和原植物石框。背景按原构图重绘为明亮卡通环境；本体补上暖石倒角、浅凹槽及柔和接缝阴影。",
  "cliff": "保留48格异形断层和原缺口。沿参考图绘制蓝天峡谷与水面；石台补厚度、圆润包边、砂岩切面和少量原位置植物。",
  "crystal": "保留40格阶梯菱形及原冰台结构。雪山与冰湖保持原构图；本体补蓝白冰层、浅槽受光、冰面侧切和积雪边缘。",
  "ruins": "保留54个可玩格和10座原障碍柱。原神庙、石柱和台阶重绘为明亮石构；本体补暖石板倒角、槽内阴影、祭坛切面。",
  "furnace": "保留52格收口平台、原支架和炉口。原炉厅重绘为卡通石构与暖光；本体补耐火石材层次、柔和包边、厚实侧面与边缝热光。"
};
const raster=await createRasterizer();
try{
// Show the actual playable footprint, never the square source texture as a board.
for(const m of MAPS){
 const board=await fs.readFile(path.join(root,'dist',m.assets.board));
 const uri='data:image/svg+xml;base64,'+board.toString('base64');
 const clip=m.terrain.cells.flatMap((s,i)=>s==='hole'?[]:[`<rect x="${i%8*60}" y="${Math.floor(i/8)*60}" width="60" height="60"/>`]).join('');
 let obstacles='';
 if(m.assets.obstacle){const source=await fs.readFile(path.join(root,'dist',m.assets.obstacle));const obstacleURI='data:image/svg+xml;base64,'+source.toString('base64');obstacles=m.terrain.cells.flatMap((s,i)=>s!=='obstacle'?[]:[`<image x="${i%8*60+1.8}" y="${Math.floor(i/8)*60+1.8}" width="56.4" height="56.4" href="${obstacleURI}"/>`]).join('');}
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="480" height="480"><defs><clipPath id="footprint">${clip}</clipPath></defs><g clip-path="url(#footprint)"><image width="480" height="480" href="${uri}"/>${obstacles}</g></svg>`;
 await fs.writeFile(path.join(dir,`${m.id}-body.png`),await raster.render(Buffer.from(svg)));
 for(const [kind,src]of Object.entries({background:m.assets.backdrop,frame:m.assets.frame})){
  const bytes=await fs.readFile(path.join(root,'dist',src)),mime=src.endsWith('.webp')?'image/webp':'image/svg+xml';
  let width=kind==='background'?1000:600,height;
  if(mime==='image/svg+xml'){const v=bytes.toString().match(/viewBox="([^"]+)"/)[1].split(' ').map(Number);height=Math.round(width*v[3]/v[2]);}
  else {const meta=await sharp(bytes).metadata();height=Math.round(width*meta.height/meta.width);}
  await fs.writeFile(path.join(dir,`${m.id}-${kind}.png`),await raster.render(bytes,{mime,width,height}));
 }
}
}finally{await raster.close();}
const enc=async name=>'data:image/png;base64,'+(await fs.readFile(path.join(dir,name))).toString('base64');
const sections=[];
for(const m of MAPS){
 const images=Object.fromEntries(await Promise.all(['before','after','background','frame','body','board'].map(async k=>[k,await enc(`${m.id}-${k}.png`)])));
 sections.push(`<section id="${m.id}"><h2>${m.name}</h2><p>${descriptions[m.id]}</p><div class="comparison"><img alt="${m.name}实际战斗画面" src="${images.after}" data-before="${images.before}" data-after="${images.after}"><div class="switch"><button data-mode="before">上一版</button><button data-mode="after" class="selected">本轮原画精修</button></div></div><details open><summary>背景 · 原轮廓外框 · 棋盘本体</summary><div class="parts">${[['background','背景'],['frame','外框（透明装饰层）'],['body','棋盘本体（按原地形裁剪）']].map(([k,t])=>`<figure><img alt="${m.name}${t}" src="${images[k]}"><figcaption>${t}</figcaption></figure>`).join('')}</div><figure class="closeup"><img alt="${m.name}棋盘实装近景" src="${images.board}"><figcaption>实际棋盘近景</figcaption></figure></details></section>`);
}
const html=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>方块乱斗 · 背景棋盘原画精修</title><style>*{box-sizing:border-box}body{margin:0;background:#edf4ed;color:#344747;font:16px/1.65 "Microsoft YaHei",sans-serif}main{max-width:1450px;margin:auto;padding:28px}h1{font-size:27px;margin-bottom:8px}p{margin:8px 0 18px}nav{display:flex;gap:12px;flex-wrap:wrap;position:sticky;top:0;padding:12px 0;background:#edf4edf5;z-index:2}a,button{color:#325251;background:#fff9e8;border:1px solid #b6c7b8;border-radius:8px;padding:8px 16px;text-decoration:none;font:inherit;cursor:pointer}section{padding:20px 0;scroll-margin-top:80px}h2{font-size:23px;margin:0}.comparison{border-radius:12px;overflow:hidden;background:#d0dfda}.comparison img{width:100%;display:block}.switch{display:flex;gap:12px;padding:12px}.selected{background:#315e58;color:white}details{padding:18px 0}summary{cursor:pointer;font-weight:bold}.parts{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:18px;margin-top:18px}figure{margin:0}figure img{width:100%;height:320px;object-fit:contain;background:repeating-conic-gradient(#dfe7e3 0 25%,#eef3ef 0 50%) 0/24px 24px;border-radius:9px}figcaption{text-align:center;margin-top:6px;color:#59706a;font-size:14px}.closeup{max-width:700px;margin:24px auto 0}.closeup img{height:auto}footer{font-size:14px;padding:24px 0}@media(max-width:750px){main{padding:16px}.parts{grid-template-columns:1fr}figure img{height:auto;max-height:480px}}</style><main><h1>背景与棋盘 · 实际游戏审查</h1><p>按认可截图的明亮卡通质感，在原地图基础上重绘背景与棋盘材质。各图均为实际游戏截图，采用相同开局；可切换上一版与本轮。原地形、卡片及玩法保持；双棋盘与记分牌已按屏幕整体居中，操作按钮独立固定在最右侧。所有图片内嵌，离线打开即可查看。</p><nav>${MAPS.map(m=>`<a href="#${m.id}">${m.name}</a>`).join('')}</nav><details><summary>你认可的美术基准（历史概念图，用于对照风格）</summary><img style="width:100%;display:block" alt="已确认美术基准" src="data:image/png;base64,"></details>${sections.join('')}<footer>本轮15个静态美术文件已原位更新：五张背景、五张本体、五个外框文件（含悬崖左右框）；森林藤蔓框沿用原成品。原地形、有效格遮罩、卡片、文字、按钮和玩法文件已核对保持。</footer></main><script>document.querySelectorAll('.switch button').forEach(b=>b.onclick=()=>{const box=b.closest('.comparison');box.querySelector('img').src=box.querySelector('img').dataset[b.dataset.mode];box.querySelectorAll('button').forEach(n=>n.classList.toggle('selected',n===b));});</script></html>`;
await fs.writeFile(path.join(dir,'背景棋盘精修预览.html'),html);
await fs.writeFile(path.join(dir,'index.html'),html);
// A compact real screenshot comparison for inline review.
const inputs=[];
for(const [i,side] of ['before','after'].entries())inputs.push({input:await sharp(path.join(dir,`cliff-${side}.png`)).resize(1000).png().toBuffer(),left:0,top:i*583+20});
const labels=Buffer.from('<svg width="1000" height="1186"><text x="16" y="16" font-family="Microsoft YaHei" font-size="14" fill="#344747">上一版</text><text x="16" y="599" font-family="Microsoft YaHei" font-size="14" fill="#344747">本轮原画精修 · 保留48格异形石台</text></svg>');
inputs.push({input:labels,left:0,top:0});
await sharp({create:{width:1000,height:1186,channels:4,background:'#edf4ed'}}).composite(inputs).png().toFile(path.join(dir,'cliff-comparison.png'));
console.log('Built embedded five-map painted-art review.');
